mapper.select:
SELECT COUNT(DISTINCT user_id)
FROM tb_user_submit
WHERE create_time >= #{startTime}

SELECT r.user_code AS userCode, r.fail_output AS failOutput FROM ( SELECT user_code, fail_output, create_time, submit_id, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY create_time DESC, submit_id DESC) AS rn FROM tb_user_submit WHERE question_id = #{questionId} AND pass = #{notPass}
AND fail_case_id = #{caseId}
) r WHERE r.rn = 1 ORDER BY r.create_time DESC, r.submit_id DESC LIMIT #{limit}
